SELECT DISTINCT object_id FROM proj_task_business_link
WHERE tenant_id=#{query.tenantId} AND project_id=#{query.projectId}

  AND owner_context=#{query.ownerContext} AND object_type=#{query.objectType}
  AND (node_execution_id IS NULL OR node_execution_id <> #{query.currentExecutionId})


        AND object_id IN #{id}

    AND 1=0

mapper.update:
UPDATE proj_task_business_link
SET unlinked_by = #{query.actorId}, unlinked_at = #{query.unlinkedAt},
    updater = #{query.actorId}, update_time = #{query.unlinkedAt}, version = version + 1
WHERE tenant_id = #{query.tenantId} AND project_id = #{query.projectId}

  AND id = #{query.linkId} AND version = #{query.expectedVersion}
  AND unlinked_at IS NULL AND active_marker = 1 AND linked_at <= #{query.unlinkedAt}
